"""Estruturas de dados do motor (plan.md §3). Núcleo puro: sem I/O."""
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal
from enum import Enum


class Status(Enum):
    APROVADA = "aprovada"
    PARCIAL = "parcial"
    RECUSADA = "recusada"
    ESTORNO = "estorno"


@dataclass(frozen=True)
class Despesa:
    id: str
    data: date
    categoria: str
    descricao: str
    fornecedor: str
    valor: Decimal
    tem_nota_fiscal: bool


@dataclass(frozen=True)
class Solicitacao:
    colaborador: dict
    competencia: str
    inicio: date
    fim: date
    despesas: tuple[Despesa, ...]


@dataclass(frozen=True)
class Contexto:
    competencia: str
    datas_em_viagem: frozenset[date] = field(default_factory=frozenset)


@dataclass(frozen=True)
class Parecer:
    despesa: Despesa
    valor_reembolsavel: Decimal
    status: Status
    regras_aplicadas: tuple[str, ...]
    justificativa: str

    @property
    def valor_glosado(self) -> Decimal:
        return self.despesa.valor - self.valor_reembolsavel


@dataclass(frozen=True)
class Resultado:
    solicitacao: Solicitacao
    pareceres: tuple[Parecer, ...]

    @property
    def total_lancado(self) -> Decimal:
        return sum((p.despesa.valor for p in self.pareceres), Decimal("0.00"))

    @property
    def total_reembolsavel(self) -> Decimal:
        return sum((p.valor_reembolsavel for p in self.pareceres), Decimal("0.00"))

    @property
    def total_glosado(self) -> Decimal:
        return self.total_lancado - self.total_reembolsavel

    @property
    def quantidade_por_status(self) -> dict[Status, int]:
        contagem = {status: 0 for status in Status}
        for parecer in self.pareceres:
            contagem[parecer.status] += 1
        return contagem

"""Le o arquivo de entrada e produz uma Solicitacao (plan.md secao 2, DT-001).

Entrada invalida e rejeitada, nao adivinhada (spec.md §3, §9) — ErroDeEntrada
nomeia o campo ausente ou de tipo invalido e nenhuma Solicitacao parcial e
devolvida.
"""
import json
from datetime import date
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

from src.motor.modelo import Despesa, Solicitacao

DUAS_CASAS = Decimal("0.01")

CAMPOS_COLABORADOR = ("id", "nome", "centro_custo")
CAMPOS_PERIODO = ("competencia", "inicio", "fim")
CAMPOS_DESPESA = ("id", "data", "categoria", "descricao", "fornecedor", "valor", "tem_nota_fiscal")


class ErroDeEntrada(Exception):
    """Campo obrigatorio ausente ou de tipo invalido na entrada."""


def carregar(caminho: str) -> Solicitacao:
    with open(caminho, "r", encoding="utf-8") as arquivo:
        dados = json.load(arquivo, parse_float=Decimal)
    return _para_solicitacao(dados)


def _arredondar(valor: Decimal) -> Decimal:
    return valor.quantize(DUAS_CASAS, rounding=ROUND_HALF_UP)


def _exigir(dados: dict, chave: str, rotulo: str):
    if not isinstance(dados, dict) or chave not in dados:
        raise ErroDeEntrada(f"Campo obrigatorio ausente: {rotulo}")
    return dados[chave]


def _exigir_data(dados: dict, chave: str, rotulo: str) -> date:
    valor = _exigir(dados, chave, rotulo)
    try:
        return date.fromisoformat(valor)
    except (TypeError, ValueError):
        raise ErroDeEntrada(f"Campo invalido: {rotulo}") from None


def _para_despesa(dados: dict, indice: int) -> Despesa:
    rotulo_base = f"despesas[{indice}]"
    for campo in CAMPOS_DESPESA:
        _exigir(dados, campo, f"{rotulo_base}.{campo}")

    data = _exigir_data(dados, "data", f"{rotulo_base}.data")

    try:
        valor = _arredondar(Decimal(dados["valor"]))
    except (InvalidOperation, TypeError, ValueError):
        raise ErroDeEntrada(f"Campo invalido: {rotulo_base}.valor") from None

    if not isinstance(dados["tem_nota_fiscal"], bool):
        raise ErroDeEntrada(f"Campo invalido: {rotulo_base}.tem_nota_fiscal")

    return Despesa(
        id=dados["id"],
        data=data,
        categoria=dados["categoria"],
        descricao=dados["descricao"],
        fornecedor=dados["fornecedor"],
        valor=valor,
        tem_nota_fiscal=dados["tem_nota_fiscal"],
    )


def _para_solicitacao(dados: dict) -> Solicitacao:
    colaborador = _exigir(dados, "colaborador", "colaborador")
    periodo = _exigir(dados, "periodo", "periodo")
    despesas_dados = _exigir(dados, "despesas", "despesas")

    for campo in CAMPOS_COLABORADOR:
        _exigir(colaborador, campo, f"colaborador.{campo}")
    for campo in CAMPOS_PERIODO:
        _exigir(periodo, campo, f"periodo.{campo}")

    inicio = _exigir_data(periodo, "inicio", "periodo.inicio")
    fim = _exigir_data(periodo, "fim", "periodo.fim")

    if not isinstance(despesas_dados, list):
        raise ErroDeEntrada("Campo invalido: despesas")

    despesas = tuple(_para_despesa(item, indice) for indice, item in enumerate(despesas_dados))

    return Solicitacao(
        colaborador=colaborador,
        competencia=periodo["competencia"],
        inicio=inicio,
        fim=fim,
        despesas=despesas,
    )

"""Formata Resultado como documento de saída (spec.md §4).

É a única fronteira onde Decimal vira texto: json.dump nunca recebe um
Decimal cru (DT-001).
"""
import json

from src.motor.modelo import Parecer, Resultado


def _valor(valor) -> str:
    return f"{valor:.2f}"


def _item(parecer: Parecer) -> dict:
    return {
        "id": parecer.despesa.id,
        "data": parecer.despesa.data.isoformat(),
        "categoria": parecer.despesa.categoria,
        "valor_lancado": _valor(parecer.despesa.valor),
        "valor_reembolsavel": _valor(parecer.valor_reembolsavel),
        "valor_glosado": _valor(parecer.valor_glosado),
        "status": parecer.status.value,
        "regras_aplicadas": list(parecer.regras_aplicadas),
        "justificativa": parecer.justificativa,
    }


def para_documento(resultado: Resultado) -> dict:
    solicitacao = resultado.solicitacao
    return {
        "colaborador": solicitacao.colaborador,
        "periodo": {
            "competencia": solicitacao.competencia,
            "inicio": solicitacao.inicio.isoformat(),
            "fim": solicitacao.fim.isoformat(),
        },
        "resumo": {
            "total_lancado": _valor(resultado.total_lancado),
            "total_reembolsavel": _valor(resultado.total_reembolsavel),
            "total_glosado": _valor(resultado.total_glosado),
            "quantidade_por_status": {
                status.value: quantidade
                for status, quantidade in resultado.quantidade_por_status.items()
            },
        },
        "itens": [_item(parecer) for parecer in resultado.pareceres],
    }


def salvar(resultado: Resultado, caminho: str) -> None:
    documento = para_documento(resultado)
    with open(caminho, "w", encoding="utf-8") as arquivo:
        json.dump(documento, arquivo, ensure_ascii=False, indent=2)
        arquivo.write("\n")

"""Exporta os transcripts do Claude Code para docs/sessions/.

Alternativa ao `/export`, que nao funciona nesta maquina. Ver FAQ.md e o
README.md deste diretorio. Nao faz parte do produto: e utilitario de processo,
nao roda em producao e nao e coberto por task da spec.

Uso, a partir da raiz do repositorio:

    python docs/sessions/_exportar.py
"""
import json
import os
import re
import shutil
import sys
from glob import glob

SLUG = "c--Users-vitor-Documents-sdd-desafio"
ORIGEM = os.path.join(os.path.expanduser("~"), ".claude", "projects", SLUG)
DESTINO = os.path.join("docs", "sessions")

# Rotulo de cada sessao, por prefixo do UUID. Acrescente conforme surgirem.
ROTULOS = {
    "021469dd": "01-abertura-interrompida",
    "b2a2418d": "02-especificacao-spec-plan-tasks",
    "da3fa182": "03-implementacao-t001-t022",
}

RUIDO = ("system-reminder", "ide_selection", "ide_opened_file", "local-command-caveat")


def blocos(registro):
    conteudo = registro.get("message", {}).get("content")
    if isinstance(conteudo, str):
        return [{"type": "text", "text": conteudo}]
    return conteudo if isinstance(conteudo, list) else []


def limpa(texto):
    for tag in RUIDO:
        texto = re.sub(rf"<{tag}>.*?</{tag}>", "", texto, flags=re.S)
    return texto.strip()


def renderiza(origem, destino, titulo):
    registros = [json.loads(l) for l in open(origem, encoding="utf-8") if l.strip()]
    marcas = [r.get("timestamp") for r in registros if r.get("timestamp")]
    periodo = f"{marcas[0][:16]} a {marcas[-1][11:16]}" if marcas else "?"

    linhas = [
        f"# {titulo}\n",
        f"**Periodo:** {periodo} · **Registros:** {len(registros)}",
        f"**Origem:** `{os.path.basename(origem)}` (copia crua no mesmo diretorio)\n",
        "> Renderizacao legivel do transcript. O `.jsonl` ao lado e a fonte",
        "> inalterada — em caso de divergencia, vale ele.\n",
        "---\n",
    ]

    for registro in registros:
        papel = registro.get("type")
        if papel not in ("user", "assistant"):
            continue
        for bloco in blocos(registro):
            if not isinstance(bloco, dict):
                continue
            tipo = bloco.get("type")

            if tipo == "text":
                texto = limpa(bloco.get("text", ""))
                if texto:
                    quem = "Usuario" if papel == "user" else "Claude"
                    linhas.append(f"### {quem}\n\n{texto}\n")

            elif tipo == "tool_use":
                entrada = json.dumps(bloco.get("input", {}), ensure_ascii=False)
                if len(entrada) > 400:
                    entrada = entrada[:400] + " …(truncado)"
                linhas.append(
                    f"<details><summary>🔧 <code>{bloco.get('name', '?')}</code></summary>\n\n"
                    f"```json\n{entrada}\n```\n</details>\n"
                )

            elif tipo == "tool_result":
                conteudo = bloco.get("content")
                if isinstance(conteudo, str):
                    texto = conteudo
                elif isinstance(conteudo, list):
                    texto = " ".join(
                        p.get("text", "") for p in conteudo if isinstance(p, dict)
                    )
                else:
                    texto = ""
                texto = texto.strip()
                if not texto:
                    continue
                if len(texto) > 600:
                    texto = texto[:600] + "\n…(resultado truncado — ver .jsonl)"
                linhas.append(
                    f"<details><summary>↩️ resultado</summary>\n\n```\n{texto}\n```\n</details>\n"
                )

    open(destino, "w", encoding="utf-8").write("\n".join(linhas))


def main():
    if not os.path.isdir(ORIGEM):
        sys.exit(f"Diretorio de transcripts nao encontrado: {ORIGEM}")
    os.makedirs(DESTINO, exist_ok=True)

    encontrados = sorted(glob(os.path.join(ORIGEM, "*.jsonl")), key=os.path.getmtime)
    if not encontrados:
        sys.exit(f"Nenhum .jsonl em {ORIGEM}")

    for caminho in encontrados:
        prefixo = os.path.basename(caminho)[:8]
        rotulo = ROTULOS.get(prefixo)
        if rotulo is None:
            print(f"[aviso] sessao {prefixo} sem rotulo em ROTULOS — pulada")
            continue
        shutil.copyfile(caminho, os.path.join(DESTINO, rotulo + ".jsonl"))
        renderiza(caminho, os.path.join(DESTINO, rotulo + ".md"), f"Sessao {rotulo}")
        print(f"exportada: {rotulo}")


if __name__ == "__main__":
    main()

